 let state;try{state={...defaultState,...JSON.parse(localStorage.getItem('rocket-save')||'{}')};state.inventory=Array.isArray(state.inventory)?state.inventory:defaultState.inventory;state.upgrades={...defaultState.upgrades,...state.upgrades}}catch{state=structuredClone(defaultState)}
 let currentJob=null,encounter=null,toastTimer;
 function save(){localStorage.setItem('rocket-save',JSON.stringify(state));render()}
 function currentRank(){let found=0;ranks.forEach((r,i)=>{if(state.rep>=r.rep)found=i});return found}

