 function missionCard(job){return `<article class="mission"><div class="mission-icon">${job.icon}</div><div><h3>${job.title}</h3><p>${job.desc}</p><div class="mission-tags"><span>◈ ${job.credits} ₽</span><span>◆ +${job.rep} REP</span><span>⚑ ${['LOW','MODERATE','HIGH'][job.difficulty-1]} RISK</span></div></div><button class="btn" onclick="startMission('${job.id}')">DISPATCH →</button></article>`}
 function renderRight(){const crew=state.inventory.slice(0,3);let upgrades=[['quarters','Crew quarters','More hands make better odds.',75,1],['lab','Snagging gear','Better tools improve steal chance.',100,2],['training','Field training','Your Pokémon gain extra mission power.',125,1]];document.getElementById('rightContent').innerHTML=`<section class="sidecard"><div class="sidehead"><h3>Active crew</h3><button onclick="setView('roster')">VIEW ALL</button></div>${crew.map(p=>`<div class="crew"><div class="creature">${p.emoji}</div><div class="creature-info"><b>${p.name}</b><span>${p.type} · POWER ${p.power}</span></div><span class="level">LV.${p.level}</span></div>`).join('')}${state.inventory.length>3?`<div class="crew-more">+ ${state.inventory.length-3} more on roster</div>`:''}</section><section class="sidecard"><div class="sidehead"><h3>Hideout upgrades</h3><button onclick="setView('base')">MANAGE</button></div>${upgrades.map(([id,name,desc,cost,rank])=>{let unlocked=currentRank()>=rank,lv=state.upgrades[id];return `<div class="upgrade"><div class="up-row"><span class="up-title">${name}</span><span class="up-level">${unlocked?`LV. ${lv}`:'🔒'}</span></div><div class="up-desc">${unlocked?desc:`Unlocks at ${ranks[rank].short} rank`}</div><div class="up-action"><span class="price">◈ ${cost+lv*50} ₽</span><button class="btn secondary" ${!unlocked||state.credits<cost+lv*50?'disabled':''} onclick="buyUpgrade('${id}')">UPGRADE</button></div></div>`}).join('')}</section>`}
 function renderRoster(){document.getElementById('mainContent').innerHTML=`<div class="welcome"><div><div class="eyebrow">FIELD ASSETS</div><h1>Pokémon roster</h1><p>Your partners in crime. Every one taken fair and square.</p></div><span class="rank-pill">◉ &nbsp;${state.inventory.length} IN CUSTODY</span></div>${rankBlock()}<div class="heading"><div><h2>Available partners</h2><div class="sub">Higher power increases your chance of a clean snatch.</div></div></div><div class="sidecard roster-grid">${state.inventory.length?state.inventory.map(p=>`<div class="roster-row"><div class="creature">${p.emoji}</div><div class="creature-info"><b>${p.name}</b><span>${p.type} type · POWER ${p.power}</span></div><span class="level">LV. ${p.level}</span></div>`).join(''):'<div class="empty">No Pokémon in your roster yet.<br>Take a field mission to recruit your first partner.</div>'}</div>`;renderRight()}
 function renderBase(){const boss=currentRank()===3;let tiles=[['🛏️','Crew quarters',state.upgrades.quarters,'More Rocket grunts join your operation.'],['🧪','Snagging gear',state.upgrades.lab,'Prototype tech helps secure wild Pokémon.'],['🥊','Training room',state.upgrades.training,'Your Pokémon get stronger with every job.']];document.getElementById('mainContent').innerHTML=`<div class="welcome"><div><div class="eyebrow">TEAM ROCKET HIDEOUT</div><h1>${boss?'A growing empire.':'Your place in the shadows.'}</h1><p>${boss?'As boss, you can expand the hideout and build a syndicate.':'Earn promotions to unlock new hideout facilities.'}</p></div><span class="rank-pill">⌂ &nbsp;${boss?'SECTOR '+state.baseSize:'TIER '+(currentRank()+1)}</span></div>${rankBlock()}<div class="heading"><div><h2>Hideout facilities</h2><div class="sub">Permanent upgrades for your operation.</div></div></div><div class="base-grid">${tiles.map(([icon,name,lv,desc],i)=>`<article class="base-tile ${currentRank()<i+1?'locked':''}"><div class="tile-icon">${icon}</div><h3>${name} ${currentRank()>=i+1?`<span style="color:var(--gold);font:9px var(--mono)">LV.${lv}</span>`:''}</h3><p>${currentRank()<i+1?`Unlock at ${ranks[i+1].short} rank`:desc}</p></article>`).join('')}</div>${boss?`<section class="sidecard" style="margin-top:13px"><div class="sidehead"><h3>Hideout expansion</h3><span class="up-level">SECTOR ${state.baseSize}</span></div><p style="color:#a3a5ad;font-size:11px;line-height:1.55">You have the authority to grow your operation. Each expansion opens a new sector and brings passive income from the underground.</p><div class="up-action"><span class="price">◈ ${300+state.baseSize*250} ₽</span><button class="btn" ${state.credits<300+state.baseSize*250?'disabled':''} onclick="expandBase()">EXPAND HIDEOUT</button></div></section>`:`<section class="sidecard" style="margin-top:13px"><div class="eyebrow">NEXT MILESTONE</div><h3 style="font:600 15px var(--display);margin:8px 0">${boss?'Boss of Team Rocket':'Rise through the ranks'}</h3><p style="color:#9da0a7;font-size:11px;line-height:1.6;margin:0">${boss?'Your organization is yours to shape.':`Reach ${ranks[Math.min(currentRank()+1,3)].name} to unlock more of your hideout. ${nextRank()?.rep-state.rep||0} reputation to go.`}</p></section>`}`;renderRight()}
-function startMission(id){currentJob=jobs.find(j=>j.id===id);if(!currentJob)return;const seen=new Set(state.inventory.map(p=>p.name));let eligible=species.filter(s=>!seen.has(s.name));if(!eligible.length)eligible=species;encounter=eligible[Math.floor(Math.random()*eligible.length)];const power=totalPower()*.45+(state.upgrades.training*.75),gear=state.upgrades.lab*9;const chance=Math.max(22,Math.min(91,70+power*2+gear-currentJob.difficulty*15));openModal(`<div class="modal-top"><div><div class="eyebrow">${currentJob.place}</div><h2>Target in sight</h2></div><button class="close" onclick="closeModal()">×</button></div><p class="modal-copy">Your lookout spotted a trainer with a <b>${encounter.name}</b>. Your crew is in position. How do you want to make the grab?</p><div class="encounter"><div class="bigmon">${encounter.emoji}</div><h3>${encounter.name}</h3><p>${encounter.type} type · EST. POWER ${encounter.power}</p><div class="odds"><span>SNAG SUCCESS <b>~${chance}%</b></span><span>CREW POWER <b>${Math.round(power*10)/10}</b></span></div></div><div class="strategy"><button onclick="resolveMission('sneak',${chance})"><b>◌ &nbsp;Stay stealthy</b><span>Lower risk. A careful, measured play.</span></button><button onclick="resolveMission('snag',${chance})"><b>✦ &nbsp;Go for the snag</b><span>Best chance to claim the Pokémon.</span></button></div><p style="font:9px var(--mono);color:var(--muted);text-align:center;margin:13px 0 0">Crew earns mission rewards either way. No partner left behind.</p>`)}
+function startMission(id){currentJob=jobs.find(j=>j.id===id);if(!currentJob)return;const seen=new Set(state.inventory.map(p=>p.name));let eligible=species.filter(s=>!seen.has(s.name));if(!eligible.length)eligible=species;encounter=eligible[Math.floor(Math.random()*eligible.length)];const power=totalPower()*.45+(state.upgrades.training*.75),gear=state.upgrades.lab*9;const chance=Math.max(22,Math.min(91,70+power*2+gear-currentJob.difficulty*15));openModal(`<div class="modal-top"><div><div class="eyebrow">${currentJob.place}</div><h2>Target in sight</h2></div><button class="close" onclick="closeModal()">×</button></div><p class="modal-copy">Your lookout spotted a trainer with a <b>${encounter.name}</b>. Your crew is in position. How do you want to make the grab?</p><div class="encounter"><div class="bigmon">${encounter.emoji}</div><h3>${encounter.name}</h3><p>${encounter.type} type · EST. POWER ${encounter.power}</p><div class="odds"><span>SNAG SUCCESS <b>~${Math.round(chance)}%</b></span><span>CREW POWER <b>${Math.round(power*10)/10}</b></span></div></div><div class="strategy"><button onclick="resolveMission('sneak',${chance})"><b>◌ &nbsp;Stay stealthy</b><span>Lower risk. A careful, measured play.</span></button><button onclick="resolveMission('snag',${chance})"><b>✦ &nbsp;Go for the snag</b><span>Best chance to claim the Pokémon.</span></button></div><p style="font:9px var(--mono);color:var(--muted);text-align:center;margin:13px 0 0">Crew earns mission rewards either way. No partner left behind.</p>`)}
 function resolveMission(strategy,chance){let odds=strategy==='sneak'?Math.min(96,chance+7):chance;let success=Math.random()*100<odds;let credits=Math.round(currentJob.credits*(success?1:.7));let rep=Math.round(currentJob.rep*(success?1:.7));let caught=success&&Math.random()*100<(strategy==='snag'?91:68);let recruit=null;if(caught){recruit={...encounter,level:Math.max(1,Math.floor(Math.random()*3)+1),id:state.nextId++};state.inventory.push(recruit)}state.credits+=credits;state.rep+=rep;state.missions++;if(state.upgrades.training>0)state.inventory.forEach(p=>{p.level+=Math.random()<.25?1:0});let promoted=nextRank()&&state.rep>=nextRank().rep;let rewardText=`<div class="result-rewards"><span class="reward">◈ +${credits} ₽</span><span class="reward">◆ +${rep} REP</span></div>`;let recruitText=recruit?`<br><b style="color:var(--green)">${recruit.emoji} ${recruit.name} joined the crew!</b>`:success?'<br>The target escaped in the confusion.':'<br>Your crew got away safely, but the target slipped through.';closeModal();openModal(`<div class="result"><div class="result-icon">${recruit?'🎯':success?'🕶️':'💨'}</div><div class="eyebrow">${success?'OPERATION COMPLETE':'CLEAN GETAWAY'}</div><h2>${recruit?'Asset secured!':success?'A tidy little operation.':'They got away this time.'}</h2><p>${success?'Your crew pulled off the job without a hitch.':`Your crew made a quick exit with some loot.`}${recruitText}</p>${rewardText}${promoted?`<div style="color:var(--gold);font:11px var(--mono);margin-bottom:13px">★ PROMOTION UNLOCKED — ${ranks[currentRank()].name.toUpperCase()} ★</div>`:''}<button class="btn" style="width:100%" onclick="closeModal();setView('${currentRank()===3?'base':'dashboard'}')">${promoted?'CLAIM YOUR NEW RANK':'BACK TO HQ'}</button></div>`);save()}
 function openModal(html){document.getElementById('modal').innerHTML=html;document.getElementById('modalBackdrop').classList.add('open')};function closeModal(){document.getElementById('modalBackdrop').classList.remove('open')}
 function buyUpgrade(id){let prices={quarters:75+state.upgrades.quarters*50,lab:100+state.upgrades.lab*50,training:125+state.upgrades.training*50};let unlock={quarters:1,lab:2,training:1};if(currentRank()<unlock[id]||state.credits<prices[id])return;state.credits-=prices[id];state.upgrades[id]++;if(id==='quarters'){state.inventory.push({name:'Rocket Grunt',emoji:'🕵️',type:'Recruit',power:2,level:1,id:state.nextId++})}if(id==='training')state.inventory.forEach(p=>{p.level++});toast(`${id==='quarters'?'A new grunt joined the crew!':id==='lab'?'Snagging gear upgraded!':'Training room improved!'}`);save()}
 function expandBase(){let cost=300+state.baseSize*250;if(currentRank()!==3||state.credits<cost)return;state.credits-=cost;state.baseSize++;toast(`Hideout expanded to sector ${state.baseSize}!`);save()}
